export const KARTU_HAFALAN_HTML: string = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Kartu Hafalan · Sesi Berurutan, Mode Kelas dan Tim</title>\n<style>\n  :root {\n    --teal: #1F4A4E; --teal2: #255759; --teal3: #2F6D72;\n    --krem: #fdfaf2; --emas: #ffd98a; --emas-gelap: #caa53d;\n    --gelap: #14343a; --garis: #7fa8a0;\n    --sekunder: #e8f0ec; --keterangan: #4a6a66; --batang: #dcebe4;\n    --subteks: #e7f0e9; --teksterang: #f3ead8;\n  }\n  body.tema-zamrud { --teal: #0B3D2E; --teal2: #14532D; --teal3: #1E7A4F; --krem: #FBF3DF;\n    --emas: #F5C04A; --emas-gelap: #C9922E; --gelap: #123128; --garis: #7FA88F;\n    --sekunder: #E9F2E4; --keterangan: #4A6A58; --batang: #DDEBD8; --subteks: #EAF3E4; }\n  body.tema-biru { --teal: #12275A; --teal2: #1B3A7A; --teal3: #2B55A0; --krem: #F8F4EA;\n    --emas: #FFB84D; --emas-gelap: #D98E1F; --gelap: #16233F; --garis: #8AA0C8;\n    --sekunder: #E8EDF7; --keterangan: #55648A; --batang: #DCE4F2; --subteks: #E9EDF9; }\n  body.tema-terang { --teal: #1E6B74; --teal2: #227C88; --teal3: #1F7A84; --krem: #FFFDF4;\n    --emas: #FFC93F; --emas-gelap: #D9A41F; --gelap: #123A3E; --garis: #7FB5AE;\n    --sekunder: #E6F4F1; --keterangan: #49716C; --batang: #D8EDE9; --subteks: #FFFFFF; --teksterang: #FFFFFF; }\n  body { font-family: system-ui, \"Segoe UI\", sans-serif; margin: 0; color: var(--teksterang);\n    background:\n      radial-gradient(1100px 560px at 88% -5%, rgba(255,217,138,.16), transparent 60%),\n      radial-gradient(900px 520px at -12% 108%, rgba(255,255,255,.09), transparent 55%),\n      linear-gradient(160deg, var(--teal), var(--teal2) 55%, var(--teal3)) fixed; }\n  .barisTema { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin: 4px 0 10px; }\n  .barisTema .labelTema { font-size: 13px; font-weight: 700; }\n  .btnTema { display: inline-flex; align-items: center; gap: 7px; padding: 12px 15px; font-size: 13px; font-weight: 700;\n    border-radius: 999px; border: 2px solid rgba(255,255,255,.45); background: rgba(0,0,0,.22); color: var(--teksterang); cursor: pointer; }\n  .btnTema .contoh { width: 14px; height: 14px; border-radius: 50%; border: 2px solid var(--emas); display: inline-block; }\n  .btnTema.aktif { background: var(--emas); color: #20302a; border-color: var(--emas); }\n  main { max-width: 680px; margin: 0 auto; padding: 20px 16px 44px; }\n  h1 { font-size: 22px; margin: 8px 0 4px; font-weight: 800; letter-spacing: -.5px; }\n  p.sub { color: var(--subteks); font-size: 14px; line-height: 1.55; }\n  body.sesiAktif h1, body.sesiAktif p.sub, body.sesiAktif .barisTema { display: none; }\n  .kotak { background: var(--krem); color: var(--gelap); border-radius: 20px; padding: 16px; margin-top: 14px;\n    border: 1px solid rgba(255,255,255,.4); box-shadow: 0 24px 60px rgba(0,0,0,.30), 0 3px 10px rgba(0,0,0,.12); }\n  textarea { width: 100%; box-sizing: border-box; min-height: 200px; padding: 12px; font-size: 18px; line-height: 1.7;\n    border: 2px solid var(--garis); border-radius: 12px; text-align: left; background: #fff;\n    font-family: \"Amiri\", \"Traditional Arabic\", \"Scheherazade New\", system-ui, serif; }\n  .kotak select { max-width: 100%; }\n  textarea:focus, input:focus, select:focus { outline: 3px solid rgba(201,146,46,.45); outline-offset: 1px; }\n  button.aksi { padding: 12px 16px; font-size: 15px; font-weight: 700; border: 0; border-radius: 12px; background: var(--teal); color: #fff; cursor: pointer;\n    box-shadow: 0 8px 20px rgba(11,61,46,.25); }\n  button.aksi.sekunder { background: var(--sekunder); color: var(--teal); border: 2px solid var(--teal); }\n  .baris { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 12px; }\n  #info { font-size: 15px; font-weight: 700; color: var(--teal); }\n  #cipTahap { font-size: 11px; font-weight: 800; letter-spacing: 1px; background: var(--teal); color: var(--emas); border-radius: 999px; padding: 4px 10px; }\n  #timer { font-size: 26px; font-weight: 800; color: var(--teal); }\n  #keteranganTimer { font-size: 12px; color: var(--keterangan); }\n  .batangLuar { height: 6px; background: var(--batang); border-radius: 3px; margin-top: 6px; overflow: hidden; }\n  #batangWaktu { height: 100%; width: 100%; background: var(--emas-gelap); }\n  #statusSesi { font-size: 14px; margin-top: 12px; min-height: 64px; color: var(--teal); line-height: 1.45; }\n  #daftarRuang button.mini.benar { background: var(--sekunder); color: var(--teal); border: 2px solid var(--teal); }\n  .barisAkhiri { position: sticky; bottom: 10px; background: var(--krem); padding: 10px 0 2px; z-index: 3; }\n  .kisi { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-top: 14px; }\n  .kartu { border: 2px solid var(--teal); border-radius: 16px; padding: 10px; text-align: center; background: var(--krem); position: relative;\n    box-shadow: 0 6px 18px rgba(20,52,58,.10); }\n  .kartu .a { font-size: 30px; font-family: \"Amiri\", \"Traditional Arabic\", \"Scheherazade New\", serif; line-height: 1.7; }\n  .kartu .b { font-size: 16px; color: var(--teal); font-weight: 700; margin-top: 4px; }\n  #kisiReview .kartu { height: 224px; display: flex; flex-direction: column; box-sizing: border-box; }\n  #kisiReview .kartu.buka { height: auto; min-height: 224px; }\n  .kartu.tutup { background-color: var(--teal); color: var(--emas); cursor: pointer; align-items: center; justify-content: center;\n    background-image: radial-gradient(rgba(255,217,138,.15) 1.5px, transparent 1.7px), linear-gradient(150deg, var(--teal3), var(--teal) 70%); background-size: 16px 16px, cover;\n    box-shadow: 0 10px 24px rgba(11,61,46,.30); }\n  .kartu.tutup .tanya { font-size: 46px; font-weight: 800; line-height: 1; width: 84px; height: 84px; border-radius: 50%;\n    display: flex; align-items: center; justify-content: center; background: rgba(255,255,255,.09); border: 2px solid rgba(255,217,138,.40); }\n  .kartu.tutup .nama { font-size: 16px; font-weight: 800; margin-top: 6px; }\n  .kartu.tutup .mikro { font-size: 11px; color: var(--subteks); margin-top: 6px; min-height: 14px; }\n  .kartu.tutup .titik { position: absolute; top: 8px; right: 8px; width: 13px; height: 13px; border-radius: 50%; background: var(--emas); border: 2px solid var(--teal); }\n  .kartu.buka { border-color: var(--emas-gelap); border-width: 3px; padding: 9px;\n    box-shadow: 0 16px 36px rgba(20,52,58,.20), 0 0 0 5px rgba(255,217,138,.30); }\n  .kartu.lulus { border-color: var(--emas-gelap); align-items: center; justify-content: center; }\n  .kartu.lulus .cip { margin-top: 8px; font-size: 12px; font-weight: 800; letter-spacing: 1px; background: var(--teal); color: var(--emas); border-radius: 999px; padding: 4px 12px; }\n  .kolom { padding: 6px 4px; }\n  .kolom + .kolom { border-top: 2px dashed var(--garis); }\n  .kolom .label { font-size: 11px; color: var(--teal); text-transform: uppercase; letter-spacing: 1px; font-weight: 700; }\n  .kolom .isi { font-size: 28px; margin-top: 2px; line-height: 1.6; font-family: \"Amiri\", \"Traditional Arabic\", \"Scheherazade New\", system-ui, serif; }\n  .kolom .isi.arti { font-size: 20px; font-weight: 700; color: var(--teal); font-family: system-ui, sans-serif; }\n  .kolom.tersembunyi { cursor: pointer; flex: 1; display: flex; flex-direction: column; }\n  .penutup { flex: 1; min-height: 52px; margin-top: 4px; border-radius: 12px; background: linear-gradient(150deg, var(--teal3), var(--teal) 70%); color: var(--emas);\n    display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 2px;\n    background-image: radial-gradient(rgba(255,217,138,.16) 1.5px, transparent 1.7px); background-size: 16px 16px; }\n  .penutup .tanyaKecil { font-size: 26px; font-weight: 800; line-height: 1; }\n  .penutup .mikro { font-size: 11px; color: var(--subteks); }\n  .slotNilai { height: 48px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: auto; }\n  .slotNilai .petunjukSlot { font-size: 12px; color: var(--keterangan); }\n  button.mini { padding: 12px 16px; font-size: 14px; font-weight: 700; border-radius: 10px; border: 0; cursor: pointer; }\n  #daftarRuang > div { box-shadow: 0 4px 14px rgba(20,52,58,.10); }\n  #areaLangkah { text-align: center; padding: 26px 6px 10px; }\n  #areaLangkah .angkanya, #teksLangkah { font-size: 30px; font-weight: 800; color: var(--teal); }\n  button.mini.benar { background: var(--teal); color: #fff; }\n  button.mini.salah { background: var(--sekunder); color: var(--teal); border: 2px solid var(--teal); }\n  #areaTuntas { text-align: center; padding: 18px 6px 8px; }\n  #areaTuntas .besar { font-size: 30px; font-weight: 800; color: var(--teal); }\n  #areaTuntas .ringkas { font-size: 15px; margin-top: 8px; line-height: 1.5; }\n  #petunjukGuru { border: 2px solid var(--garis); border-radius: 12px; padding: 10px 14px; margin-bottom: 14px; background: #fff; }\n  #petunjukGuru summary { font-size: 14px; font-weight: 700; color: var(--teal); cursor: pointer; padding: 4px 0; }\n  #petunjukGuru .isiPetunjuk { font-size: 13.5px; line-height: 1.55; color: #20302a; }\n  #petunjukGuru .isiPetunjuk p { margin: 8px 0; }\n  #spandukTim { border-radius: 14px; padding: 12px 16px; font-size: 22px; font-weight: 800; text-align: center; margin-top: 12px; letter-spacing: .3px; }\n  #tallyTim, #kemajuanTim { font-size: 14px; font-weight: 700; color: var(--teal); text-align: center; margin-top: 8px; }\n  #rincianLangkah { font-size: 16px; font-weight: 700; color: var(--teal); margin-top: 8px; line-height: 1.5; }\n  #areaTimSelesai { text-align: center; padding: 26px 6px 10px; }\n  #teksTimSelesai { font-size: 30px; font-weight: 800; color: var(--teal); }\n  #subTimSelesai { font-size: 14px; color: var(--teal); margin-top: 6px; }\n  #kisiReview { transition: none; }\n  button:focus-visible, .kartu.tutup:focus-visible, .kolom.tersembunyi:focus-visible { outline: 3px solid var(--emas-gelap); outline-offset: 2px; }\n  @media (prefers-reduced-motion: no-preference) {\n    #kisiReview { transition: opacity .18s ease; }\n    .kartu.baruBuka { animation: masukKartu .18s ease-out; }\n    @keyframes masukKartu { from { opacity: 0; transform: scale(.97); } to { opacity: 1; transform: scale(1); } }\n    .kartu.flashBenar { animation: kedipBenar .25s ease; }\n    @keyframes kedipBenar { 40% { box-shadow: 0 0 0 5px var(--emas); } }\n    .kartu.flashSalah { animation: kedipSalah .25s ease; }\n    @keyframes kedipSalah { 40% { box-shadow: 0 0 0 5px #c0563a; } }\n    button.aksi:active, button.mini:active, .kartu.tutup:active, .kolom.tersembunyi:active { transform: scale(.97); }\n    button.aksi, button.mini, .kartu.tutup, .kolom.tersembunyi { transition: transform .09s ease; }\n    button.aksi:hover, button.mini:hover { transform: translateY(-1px); }\n    .kartu.tutup:hover { transform: translateY(-2px); }\n    .kartu.tutup { transition: transform .12s ease; }\n    #batangWaktu { transition: width 1s linear; }\n  }\n  @media (min-width: 640px) {\n    #kisiReview { grid-template-columns: repeat(3, 1fr); }\n  }\n  @media (min-width: 1000px) {\n    main { max-width: 1240px; padding: 26px 24px 52px; }\n    h1 { font-size: 30px; }\n    p.sub { font-size: 15px; max-width: 880px; }\n    .kotak { padding: 24px 26px; border-radius: 16px; }\n    /* Formulir dua panel: editor kiri, rak ruang kanan */\n    #kotakIsi { display: grid; grid-template-columns: minmax(0, 1fr) 400px; gap: 28px; align-items: start; }\n    #kotakIsi textarea { min-height: 330px; }\n    .panelRuang > div:first-child { margin-top: 0 !important; }\n    .panelRuang #daftarRuang { grid-template-columns: repeat(auto-fill, minmax(168px, 1fr)) !important; max-height: 540px !important; }\n    /* Papan sesi skala layar besar */\n    #kotakSesi { padding: 26px 28px; }\n    #info { font-size: 19px; }\n    #cipTahap { font-size: 13px; padding: 6px 14px; }\n    #timer { font-size: 40px; }\n    #keteranganTimer { font-size: 13px; }\n    #statusSesi { min-height: 44px; font-size: 15.5px; }\n    .kisi { gap: 16px; }\n    #kisiBelajar { grid-template-columns: repeat(4, 1fr); }\n    #kisiBelajar .kartu { min-height: 300px; display: flex; flex-direction: column; justify-content: center; padding: 20px 14px; }\n    #kisiBelajar .kolom .isi { font-size: 42px; }\n    #kisiBelajar .kolom .isi.arti { font-size: 25px; }\n    .kartu .a { font-size: 44px; }\n    .kartu .b { font-size: 20px; }\n    .kolom .label { font-size: 12px; }\n    #kisiReview { grid-template-columns: repeat(4, 1fr); }\n    #kisiReview .kartu { height: 300px; }\n    #kisiReview .kartu.buka { min-height: 300px; }\n    .kartu.tutup .tanya { font-size: 72px; width: 118px; height: 118px; }\n    #teksLangkah { font-size: 38px; }\n    .kartu.tutup .nama { font-size: 18px; }\n    .kolom .isi { font-size: 34px; }\n    .kolom .isi.arti { font-size: 23px; }\n    .penutup .tanyaKecil { font-size: 30px; }\n    .slotNilai { height: 56px; }\n    button.aksi { padding: 14px 22px; font-size: 16px; }\n    button.mini { padding: 14px 18px; font-size: 15px; }\n    #areaTuntas .besar { font-size: 38px; }\n    #areaTuntas .ringkas { font-size: 17px; }\n    #spandukTim { font-size: 28px; }\n    #teksTimSelesai { font-size: 38px; }\n  }\n  @media (min-width: 1600px) {\n    main { max-width: 1400px; }\n    #kisiBelajar .kartu { min-height: 320px; }\n    .kartu .a { font-size: 48px; }\n    #kisiReview .kartu { height: 320px; }\n    #kisiReview .kartu.buka { min-height: 320px; }\n    .kolom .isi { font-size: 36px; }\n  }\n</style>\n</head>\n<body>\n<main>\n  <div class=\"barisTema\" role=\"group\" aria-label=\"Pilih tema warna\">\n    <span class=\"labelTema\">Tema:</span>\n    <button class=\"btnTema\" data-tema=\"zamrud\"><span class=\"contoh\" style=\"background:#14532D\"></span>Zamrud</button>\n    <button class=\"btnTema\" data-tema=\"biru\"><span class=\"contoh\" style=\"background:#1B3A7A\"></span>Biru Malam</button>\n    <button class=\"btnTema\" data-tema=\"terang\"><span class=\"contoh\" style=\"background:#2A8C96\"></span>Teal Terang</button>\n  </div>\n  <h1>Kartu Hafalan</h1>\n  <p class=\"sub\">Isi daftar di bawah (satu baris satu kartu: tulisan = arti), berapa pun jumlahnya,\n  maksimal 100 kartu. Semua kartu ikut dan dibagi berurutan seperti ditulis menjadi\n  sesi sesi sebesar angka per sesi yang dipilih. Tiap sesi dihafalkan dulu selama 3 menit dalam\n  urutan tulisannya, lalu diuji dengan posisi kartu teracak: tiap kartu dua kolom, satu tampil\n  dan satu tertutup, yang tertutup diacak ulang setiap dibuka. Sesudah satu sesi dikuasai, Lanjut membawanya ke babak pengumpulan berisi semua sesi\n  sebelumnya, baru masuk sesi berikutnya. Yang tampil di layar hanya angka kemajuan. Semua\n  berjalan di perangkat ini, tanpa API dan tanpa internet.</p>\n\n  <div class=\"kotak\" id=\"kotakIsi\">\n    <div class=\"panelEditor\">\n    <details id=\"petunjukGuru\">\n      <summary>Petunjuk Guru</summary>\n      <div class=\"isiPetunjuk\">\n        <p><strong>Menyiapkan daftar.</strong> Tulis satu baris untuk satu kartu dengan format tulisan = arti, misalnya kosakata Arab beserta artinya, kata Inggris beserta artinya, atau soal beserta jawabannya. Untuk rumus yang memuat tanda sama dengan, pakai pemisah | antara soal dan jawaban. Satu daftar maksimal 100 kartu.</p>\n        <p><strong>Label kolom.</strong> Pilihan Label kolom menentukan nama kedua kolom pada kartu: Kosakata dan Terjemahan, Rumus dan Jawaban, atau Tulisan dan Arti. Pilih yang sesuai dengan isi daftar.</p>\n        <p><strong>Kartu per sesi.</strong> Semua kartu di daftar ikut serta, berurutan seperti ditulis. Angka kartu per sesi membagi daftar menjadi beberapa sesi: 12 kartu dengan angka 3 menjadi 4 sesi berisi 3 kartu. Kosongkan angka itu untuk memakai 4 kartu per sesi.</p>\n        <p><strong>Menyimpan ruang.</strong> Beri nama lalu tekan Simpan Ruang agar daftar tersimpan di perangkat ini dan bisa dibuka lagi pada pertemuan berikutnya. Ruang dapat diganti namanya, dihapus, dan dicadangkan sebagai teks lewat tombol Salin Cadangan Ruang. Ruang hanya tersimpan di perangkat dan peramban ini.</p>\n        <p><strong>Menjalankan sesi.</strong> Tekan Mulai Sesi. Tiap sesi dimulai dengan tahap hafal selama 3 menit; waktu habis membuat tahap uji mulai sendiri, atau tekan tombol Sudah Hafal, Uji Sekarang untuk mulai lebih awal. Pada tahap uji, siswa menjawab kolom tertutup dari ingatan, mengetuk kolom itu untuk memeriksa, lalu menilai sendiri dengan tombol Saya Benar atau Masih Salah. Satu kartu dianggap dikuasai sesudah dua kali jawaban benar, dan satu jawaban salah mengembalikan hitungannya. Posisi kartu diacak lagi sesudah tiap penilaian. Sesudah satu sesi dikuasai, tombol Lanjut membuka babak pengumpulan yang menguji semua kartu dari sesi pertama sampai sesi itu, baru kemudian sesi berikutnya dimulai. Babak mana pun dapat diulangi dengan tombol Ulangi Babak Ini.</p>\n        <p><strong>Mode Kelas.</strong> Satu papan untuk seluruh kelas, dimainkan bersama dengan bimbingan guru. Ini pilihan bawaan.</p>\n        <p><strong>Mode Tim Bergantian.</strong> Satu papan dimainkan bersama oleh 2 sampai 4 tim. Sesudah tiap penilaian, giliran berpindah ke tim berikutnya, dan spanduk di atas papan menunjukkan tim yang sedang bermain. Jumlah jawaban benar tiap tim dihitung dan ditampilkan sebagai angka pada panel akhir.</p>\n        <p><strong>Mode Tim Bergilir.</strong> Tiap tim mempunyai papannya sendiri yang tampil layar penuh secara bergantian. Tekan tombol Tim Berikutnya untuk berpindah ke tim berikutnya yang belum menuntaskan babak ini. Pergantian terkunci selama ada kartu yang sudah dibuka tetapi belum dinilai; nilai dulu kartu itu. Kemajuan tiap tim tersimpan persis seperti saat ditinggalkan, dan satu babak selesai bila semua tim sudah menuntaskan papannya.</p>\n        <p><strong>Aturan kloning pada mode tim.</strong> Pada tahap uji mode tim, jumlah kartu di papan selalu sama dari awal sampai akhir babak. Kartu yang sudah dikuasai hilang dari papan, dan tempatnya diisi oleh gandaan (klon) kartu yang belum dikuasai, tersebar merata. Bila tinggal satu kartu yang belum dikuasai, seluruh papan berisi klon kartu itu. Membuka dan menilai klon mana pun sama dengan menilai kartu aslinya.</p>\n        <p><strong>Kemajuan hanya angka.</strong> Layar hanya menampilkan angka kemajuan, misalnya 1/3, tanpa keterangan kartu mana yang belum dikuasai, agar siswa tidak menebak dari tanda pada kartu.</p>\n        <p><em>Video tutorial penggunaan kartu ini akan tampil di bagian ini. Untuk sementara, ikuti penjelasan tertulis di atas.</em></p>\n      </div>\n    </details>\n    <label for=\"daftar\" style=\"font-size:13px;font-weight:600;display:block\">Daftar kartu, format: tulisan = arti (untuk rumus yang memuat tanda =, pakai pemisah | antara soal dan jawaban)</label>\n    <textarea id=\"daftar\" dir=\"ltr\">كِتَابٌ = buku\nبَيْتٌ = rumah\nمَدْرَسَةٌ = sekolah\nقَلَمٌ = pena\nبَابٌ = pintu\nنَافِذَةٌ = jendela\nسَبُّورَةٌ = papan tulis\nكُرْسِيٌّ = kursi\nحَقِيبَةٌ = tas\nدَفْتَرٌ = buku tulis\nمَكْتَبٌ = meja\nمَسْجِدٌ = masjid</textarea>\n    <div style=\"margin-top:12px; display:flex; align-items:center; gap:8px; flex-wrap:wrap\">\n      <label for=\"jumlahKartu\" style=\"font-size:13px;font-weight:600\">Jumlah kartu per sesi:</label>\n      <input type=\"number\" id=\"jumlahKartu\" min=\"2\" placeholder=\"mis. 10\" style=\"width:96px; padding:9px; font-size:16px; border-radius:8px; border:2px solid var(--garis); background:#fff; color:#20302a\">\n    </div>\n    <div style=\"font-size:12px; color:var(--keterangan); margin-top:4px\">Semua kartu di daftar ikut, berurutan seperti ditulis, dibagi menjadi sesi sebesar angka ini. Misal 12 kartu dengan angka 3 menjadi 4 sesi berisi 3 kartu. Kosongkan untuk 4 kartu per sesi.</div>\n    <div style=\"margin-top:12px; display:flex; align-items:center; gap:8px; flex-wrap:wrap\">\n      <label for=\"pilihMode\" style=\"font-size:13px;font-weight:600\">Mode main:</label>\n      <select id=\"pilihMode\" style=\"padding:9px; font-size:15px; border-radius:8px; border:2px solid var(--garis); background:#fff; color:#20302a\">\n        <option value=\"kelas\">Kelas (satu papan untuk semua)</option>\n        <option value=\"gantian\">Tim Bergantian (satu papan, giliran berpindah)</option>\n        <option value=\"bergilir\">Tim Bergilir (papan sendiri, layar penuh bergantian)</option>\n      </select>\n      <span id=\"wadahTim\" style=\"display:none; align-items:center; gap:8px\">\n        <label for=\"pilihTim\" style=\"font-size:13px;font-weight:600\">Jumlah tim:</label>\n        <select id=\"pilihTim\" style=\"padding:9px; font-size:15px; border-radius:8px; border:2px solid var(--garis); background:#fff; color:#20302a\">\n          <option value=\"2\">2 tim</option>\n          <option value=\"3\">3 tim</option>\n          <option value=\"4\">4 tim</option>\n        </select>\n      </span>\n    </div>\n    <div style=\"font-size:12px; color:var(--keterangan); margin-top:4px\">Pada mode tim, kartu yang sudah dikuasai hilang dari papan dan tempatnya diisi klon kartu yang belum dikuasai, jadi jumlah kartu di papan tetap. Aturan lengkapnya ada di Petunjuk Guru di atas.</div>\n    <div style=\"margin-top:12px; display:flex; align-items:center; gap:8px; flex-wrap:wrap\">\n      <label for=\"namaRuang\" style=\"font-size:13px;font-weight:600\">Nama ruang:</label>\n      <input type=\"text\" id=\"namaRuang\" maxlength=\"60\" placeholder=\"mis. Pertemuan 1, Kosakata 1, Rumus 1\" style=\"flex:1; min-width:180px; padding:9px; font-size:15px; border-radius:8px; border:2px solid var(--garis); background:#fff; color:#20302a\">\n      <label for=\"jenisLabel\" style=\"font-size:13px;font-weight:600\">Label kolom:</label>\n      <select id=\"jenisLabel\" style=\"padding:9px; font-size:15px; border-radius:8px; border:2px solid var(--garis); background:#fff; color:#20302a\">\n        <option value=\"kosakata\">Kosakata / Terjemahan</option>\n        <option value=\"rumus\">Rumus / Jawaban</option>\n        <option value=\"umum\">Tulisan / Arti</option>\n      </select>\n      <button class=\"aksi sekunder\" id=\"btnSimpanRuang\">Simpan Ruang</button>\n      <button class=\"aksi sekunder\" id=\"btnRuangBaru\">Ruang Baru</button>\n    </div>\n    <div id=\"statusRuang\" style=\"font-size:12px; color:var(--keterangan); margin-top:4px\">Nama bebas: Pertemuan 1, Kosakata 1, Rumus 1, Rumus 2, terserah guru. Kosongkan nama untuk diisi otomatis \"Pertemuan\" berikutnya. Ruang yang sedang dibuka akan diperbarui bila disimpan lagi; mengganti nama ruang yang sudah ada bisa juga lewat tombol Nama pada kartunya.</div>\n    <div class=\"baris\">\n      <button class=\"aksi\" id=\"btnMulai\">Mulai Sesi</button>\n    </div>\n    <div id=\"statusIsi\" style=\"font-size:14px;margin-top:12px;color:#14343a\">12 kartu contoh terisi. Tekan Mulai Sesi, atau ganti dulu daftarnya dengan kosakata dars apa pun.</div>\n    </div>\n    <div class=\"panelRuang\">\n    <div style=\"font-size:13px;font-weight:600;margin-top:20px\">Ruang tersimpan di perangkat ini</div>\n    <div style=\"font-size:12px;color:var(--keterangan);margin-top:4px\">Ruang hanya tersimpan di perangkat dan peramban ini: siapa pun yang memakai perangkat ini dapat membukanya, dan ruang hilang bila data situs dibersihkan. Simpan cadangan teksnya untuk berjaga-jaga.</div>\n    <div id=\"daftarRuang\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:8px;margin-top:8px;max-height:300px;overflow:auto\"></div>\n    <div id=\"ruangKosong\" style=\"font-size:12px;color:var(--keterangan);margin-top:6px\">Belum ada ruang tersimpan. Isi daftar di atas, beri nama, lalu tekan Simpan Ruang.</div>\n    <div class=\"baris\">\n      <button class=\"aksi sekunder\" id=\"btnSalinCadangan\">Salin Cadangan Ruang</button>\n      <button class=\"aksi sekunder\" id=\"btnPulihkanCadangan\">Pulihkan dari Cadangan</button>\n    </div>\n    <div id=\"statusCadangan\" style=\"font-size:12px; color:var(--keterangan); margin-top:4px\"></div>\n    </div>\n  </div>\n\n  <div class=\"kotak\" id=\"kotakSesi\" style=\"display:none\">\n    <div style=\"display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap\">\n      <div id=\"info\"></div>\n      <span id=\"cipTahap\"></span>\n      <div style=\"text-align:right\">\n        <div id=\"timer\"></div>\n        <div id=\"keteranganTimer\"></div>\n      </div>\n    </div>\n    <div class=\"batangLuar\" id=\"batangLuar\" style=\"display:none\"><div id=\"batangWaktu\"></div></div>\n    <div id=\"statusSesi\"></div>\n\n    <div id=\"barTim\" style=\"display:none\">\n      <div id=\"spandukTim\"></div>\n      <div id=\"tallyTim\" style=\"display:none\"></div>\n      <div id=\"kemajuanTim\" style=\"display:none\"></div>\n      <div class=\"baris\" style=\"justify-content:center\">\n        <button class=\"aksi sekunder\" id=\"btnTimBerikutnya\" style=\"display:none\">Tim Berikutnya</button>\n      </div>\n    </div>\n\n    <div id=\"areaBelajar\">\n      <div class=\"kisi\" id=\"kisiBelajar\"></div>\n      <div class=\"baris\">\n        <button class=\"aksi\" id=\"btnLanjutReview\">Sudah Hafal, Uji Sekarang</button>\n      </div>\n    </div>\n\n    <div id=\"areaReview\" style=\"display:none\">\n      <div class=\"kisi\" id=\"kisiReview\" style=\"margin-top:0\"></div>\n    </div>\n\n    <div id=\"areaLangkah\" style=\"display:none\">\n      <div class=\"angkanya\" id=\"teksLangkah\"></div>\n      <div id=\"rincianLangkah\" style=\"display:none\"></div>\n      <div class=\"baris\" style=\"justify-content:center\">\n        <button class=\"aksi sekunder\" id=\"btnUlangiLangkah\">Ulangi Babak Ini</button>\n        <button class=\"aksi\" id=\"btnLanjutLangkah\">Lanjut</button>\n      </div>\n    </div>\n\n    <div id=\"areaTimSelesai\" style=\"display:none\">\n      <div id=\"teksTimSelesai\"></div>\n      <div id=\"subTimSelesai\"></div>\n      <div class=\"baris\" style=\"justify-content:center\">\n        <button class=\"aksi\" id=\"btnTimSelesaiLanjut\">Tim Berikutnya</button>\n      </div>\n    </div>\n\n    <div id=\"areaTuntas\" style=\"display:none\">\n      <div class=\"besar\">Sesi Tuntas</div>\n      <div class=\"ringkas\" id=\"ringkasTuntas\"></div>\n      <div class=\"baris\" style=\"justify-content:center\">\n        <button class=\"aksi\" id=\"btnMainLagi\">Ulangi dari Awal</button>\n      </div>\n    </div>\n\n    <div class=\"baris barisAkhiri\">\n      <button class=\"aksi sekunder\" id=\"btnUlang\">Akhiri dan Ubah Daftar</button>\n    </div>\n  </div>\n</main>\n\n<script>\nconst $ = id => document.getElementById(id);\nconst arab = t => /[\\u0600-\\u06FF]/.test(t);\nconst acak = n => Math.floor(Math.random() * n);\nconst gerakDikurangi = () => window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\nconst jeda = ms => new Promise(r => setTimeout(r, gerakDikurangi() ? 0 : ms));\nfunction kocok(arr) { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = acak(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; }\n\nlet kartu = [];        // {a, b, benar, salah, lulus} — urutan selalu seperti ditulis\nlet perSesi = 4;\nlet langkah = [];      // rangkaian babak: {jenis: \"sesi\"|\"kumpul\", ke: n}\nlet langkahKe = 0;\nlet ronde = [];        // kartu pada babak yang sedang berjalan\nlet urutan = [];       // urutan tampil kartu pada tahap uji, selalu diacak\nlet bukaIdx = -1;\nlet sisiTampil = \"a\";\nlet terjawab = false;\nlet baruBuka = false;  // animasi masuk hanya pada render sesudah membuka\nlet sibuk = false;     // kunci masukan selama pengakuan penilaian\nlet sisaBelajar = 180, jamBelajar = null;\nlet catatanMulai = \"\";\nlet generasiSesi = 0;\nlet targetWaktu = 0;\nlet editorKotor = false;\nlet modeSesi = \"kelas\";   // \"kelas\" | \"gantian\" | \"bergilir\"\nlet timSesi = 2;\nlet giliranTim = 0;       // gantian: tim yang sedang bermain\nlet timAktif = 0;         // bergilir: tim yang papannya tampil\nlet tallyTim = [0, 0, 0, 0];\nlet papanTim = [];        // bergilir: keadaan kartu per tim, sejajar dengan ronde\nconst WARNA_TIM = [\n  { latar: \"#14532D\", teks: \"#FBF3DF\" },\n  { latar: \"#1B3A7A\", teks: \"#F8F4EA\" },\n  { latar: \"#E8B93C\", teks: \"#3A2E05\" },\n  { latar: \"#9C3A2B\", teks: \"#FBEDE8\" }\n];\nconst MAKS_KARTU = 100;\nconst jedaBaca = ms => new Promise(r => setTimeout(r, ms));\nconst PASANGAN_LABEL = { kosakata: [\"Kosakata\", \"Terjemahan\"], rumus: [\"Rumus\", \"Jawaban\"], umum: [\"Tulisan\", \"Arti\"] };\nfunction labelSisi(sisi) { const p = PASANGAN_LABEL[$(\"jenisLabel\").value] || PASANGAN_LABEL.kosakata; return sisi === \"a\" ? p[0] : p[1]; }\nfunction pisahBaris(b) {\n  const t = b.trim();\n  if (!t) return null;\n  let p;\n  if (t.includes(\"|\")) { const i = t.indexOf(\"|\"); p = [t.slice(0, i), t.slice(i + 1)]; }\n  else { const i = t.indexOf(\"=\"); if (i < 0) return null; p = [t.slice(0, i), t.slice(i + 1)]; }\n  const a = p[0].trim(), bb = p[1].trim();\n  return a && bb ? { a, b: bb } : null;\n}\nfunction parseDaftar(teks) {\n  const hasil = []; let dibuang = 0; let duplikat = 0;\n  const terlihat = new Set();\n  String(teks || \"\").split(\"\\n\").forEach(b => {\n    if (!b.trim()) return;\n    const c = pisahBaris(b);\n    if (!c) { dibuang++; return; }\n    const kunci = c.a + \"\u0000\" + c.b;\n    if (terlihat.has(kunci)) duplikat++;\n    terlihat.add(kunci);\n    hasil.push({ a: c.a, b: c.b, benar: 0, salah: 0, lulus: false });\n  });\n  return { hasil, dibuang, duplikat };\n}\nfunction kunciKartu(c) { return c.a + \"\u0000\" + c.b; }\n\nfunction totalSesi() { return Math.ceil(kartu.length / perSesi); }\nfunction langkahIni() { return langkah[langkahKe]; }\nfunction labelLangkah(l) { return l.jenis === \"sesi\" ? \"Sesi \" + l.ke : \"Pengumpulan \" + l.ke; }\nfunction infoTeks() {\n  const l = langkahIni();\n  const lulus = modeSesi === \"bergilir\" && papanTim[timAktif]\n    ? papanTim[timAktif].filter(s => s.lulus).length\n    : ronde.filter(c => c.lulus).length;\n  return labelLangkah(l) + \" · \" + lulus + \"/\" + ronde.length;\n}\n\nfunction keadaanKartu(ri) {\n  if (modeSesi === \"bergilir\") return papanTim[timAktif][ri];\n  return ronde[ri];\n}\nfunction papanAktifSelesai() {\n  if (modeSesi === \"bergilir\") return papanTim.length > 0 && papanTim[timAktif].every(s => s.lulus);\n  return ronde.every(c => c.lulus);\n}\nfunction semuaTimSelesaiBabak() {\n  return papanTim.length > 0 && papanTim.every(p => p.every(s => s.lulus));\n}\nfunction susunUrutan() {\n  const n = ronde.length;\n  if (modeSesi === \"kelas\") { urutan = kocok(ronde.map((_, i) => i)); return; }\n  const belum = [];\n  for (let i = 0; i < n; i++) if (!keadaanKartu(i).lulus) belum.push(i);\n  if (!belum.length) { urutan = []; return; }\n  const slot = belum.slice();\n  let k = 0;\n  while (slot.length < n) { slot.push(belum[k % belum.length]); k++; }\n  urutan = kocok(slot);\n}\nfunction segarkanBarTim() {\n  const bar = $(\"barTim\");\n  if (modeSesi === \"kelas\") { bar.style.display = \"none\"; return; }\n  bar.style.display = \"\";\n  const aktif = modeSesi === \"gantian\" ? giliranTim : timAktif;\n  const sp = $(\"spandukTim\");\n  sp.style.background = WARNA_TIM[aktif].latar;\n  sp.style.color = WARNA_TIM[aktif].teks;\n  sp.textContent = modeSesi === \"gantian\" ? \"Giliran Tim \" + (aktif + 1) : \"Papan Tim \" + (aktif + 1);\n  if (modeSesi === \"gantian\") {\n    $(\"tallyTim\").style.display = \"\";\n    $(\"tallyTim\").textContent = \"Jawaban benar: \" + WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + tallyTim[t]).join(\"  ·  \");\n    $(\"kemajuanTim\").style.display = \"none\";\n    $(\"btnTimBerikutnya\").style.display = \"none\";\n  } else {\n    $(\"tallyTim\").style.display = \"none\";\n    $(\"kemajuanTim\").style.display = \"\";\n    $(\"kemajuanTim\").textContent = WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + (papanTim[t] ? papanTim[t].filter(s => s.lulus).length : 0) + \"/\" + ronde.length).join(\"  ·  \");\n    $(\"btnTimBerikutnya\").style.display = \"\";\n  }\n}\n\nfunction mulaiSesi() {\n  clearInterval(jamBelajar);\n  const { hasil, dibuang, duplikat } = parseDaftar($(\"daftar\").value);\n  if (hasil.length < 2) { $(\"statusIsi\").textContent = \"Isi dulu minimal 2 kartu dengan format tulisan = arti.\"; return; }\n  if (hasil.length > MAKS_KARTU) {\n    $(\"statusIsi\").textContent = \"Daftar ini berisi \" + hasil.length + \" kartu; batas satu sesi penuh adalah \" + MAKS_KARTU + \" kartu. Kurangi daftarnya dulu.\";\n    return;\n  }\n  const catatan = [];\n  if (dibuang > 0) catatan.push(dibuang + \" baris dilewati karena formatnya bukan tulisan = arti.\");\n  if (duplikat > 0) catatan.push(\"Ada \" + duplikat + \" kartu duplikat persis di daftar.\");\n  kartu = hasil;\n  modeSesi = $(\"pilihMode\").value;\n  if (![\"kelas\", \"gantian\", \"bergilir\"].includes(modeSesi)) modeSesi = \"kelas\";\n  timSesi = parseInt($(\"pilihTim\").value, 10);\n  if (![2, 3, 4].includes(timSesi)) timSesi = 2;\n  tallyTim = [0, 0, 0, 0];\n  const mintaTeks = ($(\"jumlahKartu\").value || \"\").trim();\n  const minta = parseInt(mintaTeks, 10);\n  perSesi = 4;\n  if (Number.isFinite(minta) && minta >= 2) perSesi = Math.min(minta, kartu.length);\n  else if (mintaTeks !== \"\") catatan.push(\"Angka per sesi tidak dipakai (harus 2 atau lebih); dipakai 4 per sesi.\");\n  catatanMulai = catatan.join(\" \");\n  langkah = [];\n  for (let k = 1; k <= totalSesi(); k++) { langkah.push({ jenis: \"sesi\", ke: k }); langkah.push({ jenis: \"kumpul\", ke: k }); }\n  generasiSesi++;\n  langkahKe = 0;\n  document.body.classList.add(\"sesiAktif\");\n  $(\"kotakIsi\").style.display = \"none\";\n  $(\"kotakSesi\").style.display = \"\";\n  $(\"areaTuntas\").style.display = \"none\";\n  $(\"areaLangkah\").style.display = \"none\";\n  mulaiLangkah();\n}\n\nfunction mulaiLangkah() {\n  const l = langkahIni();\n  ronde = l.jenis === \"sesi\"\n    ? kartu.slice((l.ke - 1) * perSesi, Math.min(kartu.length, l.ke * perSesi))\n    : kartu.slice(0, Math.min(kartu.length, l.ke * perSesi));\n  ronde.forEach(c => { c.benar = 0; c.salah = 0; c.lulus = false; });\n  giliranTim = 0; timAktif = 0;\n  papanTim = modeSesi === \"bergilir\"\n    ? Array.from({ length: timSesi }, () => ronde.map(() => ({ benar: 0, salah: 0, lulus: false })))\n    : [];\n  bukaIdx = -1; terjawab = false; sibuk = false;\n  $(\"areaTimSelesai\").style.display = \"none\";\n  $(\"areaLangkah\").style.display = \"none\";\n  $(\"areaTuntas\").style.display = \"none\";\n  if (l.jenis === \"sesi\") mulaiBelajar();\n  else mulaiReview();\n}\n\nfunction mulaiBelajar() {\n  clearInterval(jamBelajar);\n  $(\"areaBelajar\").style.display = \"\";\n  $(\"areaReview\").style.display = \"none\";\n  $(\"areaTuntas\").style.display = \"none\";\n  $(\"areaTimSelesai\").style.display = \"none\";\n  $(\"barTim\").style.display = \"none\";\n  $(\"cipTahap\").textContent = \"TAHAP HAFAL\";\n  $(\"info\").textContent = infoTeks();\n  const setIni = ronde;\n  $(\"kisiBelajar\").innerHTML = \"\";\n  setIni.forEach(c => {\n    const d = document.createElement(\"div\");\n    d.className = \"kartu\";\n    d.appendChild(kolomBelajar(c, \"a\"));\n    d.appendChild(kolomBelajar(c, \"b\"));\n    $(\"kisiBelajar\").appendChild(d);\n  });\n  sisaBelajar = 180;\n  targetWaktu = Date.now() + 180000;\n  $(\"timer\").textContent = \"03:00\";\n  $(\"keteranganTimer\").textContent = \"waktu habis, ujian mulai sendiri\";\n  $(\"batangLuar\").style.display = \"\";\n  $(\"batangWaktu\").style.width = \"100%\";\n  $(\"statusSesi\").textContent = \"Tahap hafal: perhatikan \" + setIni.length + \" kartu ini. Sesudah siap, akhiri tahap hafal dengan tombol Uji Sekarang.\" + (langkahKe === 0 && catatanMulai ? \" \" + catatanMulai : \"\");\n  jamBelajar = setInterval(() => {\n    const sisa = Math.max(0, Math.ceil((targetWaktu - Date.now()) / 1000));\n    sisaBelajar = sisa;\n    $(\"timer\").textContent = String(Math.floor(sisa / 60)).padStart(2, \"0\") + \":\" + String(sisa % 60).padStart(2, \"0\");\n    $(\"batangWaktu\").style.width = (sisa / 180 * 100) + \"%\";\n    if (sisa <= 0) { clearInterval(jamBelajar); mulaiReview(); }\n  }, 250);\n}\n\nfunction kolomBelajar(c, sisi) {\n  const d = document.createElement(\"div\");\n  d.className = \"kolom\";\n  const label = document.createElement(\"div\");\n  label.className = \"label\";\n  label.textContent = labelSisi(sisi);\n  d.appendChild(label);\n  const isi = document.createElement(\"div\");\n  if (sisi === \"a\") { isi.className = \"isi\"; isi.textContent = c.a; if (arab(c.a)) isi.dir = \"rtl\"; }\n  else { isi.className = \"isi arti\"; isi.textContent = c.b; if (arab(c.b)) isi.dir = \"rtl\"; }\n  d.appendChild(isi);\n  return d;\n}\n\nfunction mulaiReview() {\n  clearInterval(jamBelajar);\n  $(\"timer\").textContent = \"\";\n  $(\"keteranganTimer\").textContent = \"\";\n  $(\"batangLuar\").style.display = \"none\";\n  $(\"areaBelajar\").style.display = \"none\";\n  $(\"areaTuntas\").style.display = \"none\";\n  $(\"areaLangkah\").style.display = \"none\";\n  $(\"areaTimSelesai\").style.display = \"none\";\n  $(\"areaReview\").style.display = \"\";\n  $(\"cipTahap\").textContent = langkahIni().jenis === \"sesi\" ? \"TAHAP UJI\" : \"PENGUMPULAN\";\n  susunUrutan();\n  bukaIdx = -1; terjawab = false; sibuk = false;\n  $(\"info\").textContent = infoTeks();\n  $(\"statusSesi\").textContent = \"Ketuk satu kartu. Satu kolom tampil, satu tertutup, diacak setiap dibuka, dan posisi kartu diacak lagi sesudah tiap penilaian. Jawab yang tertutup dari ingatan, ketuk kolom tertutupnya untuk memeriksa, lalu nilai sendiri.\";\n  segarkanBarTim();\n  gambarReview();\n}\n\nfunction kolomKartu(c, sisi) {\n  const d = document.createElement(\"div\");\n  d.className = \"kolom\";\n  const label = document.createElement(\"div\");\n  label.className = \"label\";\n  label.textContent = labelSisi(sisi);\n  d.appendChild(label);\n  const tampil = (sisi === sisiTampil) || terjawab;\n  if (tampil) {\n    const isi = document.createElement(\"div\");\n    isi.className = \"isi\" + (sisi === \"b\" ? \" arti\" : \"\");\n    isi.textContent = sisi === \"a\" ? c.a : c.b;\n    if (arab(isi.textContent)) isi.dir = \"rtl\";\n    d.appendChild(isi);\n  } else {\n    d.classList.add(\"tersembunyi\");\n    const p = document.createElement(\"div\");\n    p.className = \"penutup\";\n    const t = document.createElement(\"div\"); t.className = \"tanyaKecil\"; t.textContent = \"?\";\n    const m = document.createElement(\"div\"); m.className = \"mikro\"; m.textContent = \"ketuk untuk periksa\";\n    p.appendChild(t); p.appendChild(m);\n    d.appendChild(p);\n    d.onclick = () => periksa();\n  }\n  return d;\n}\n\nfunction gambarReview() {\n  const kisi = $(\"kisiReview\");\n  kisi.innerHTML = \"\";\n  urutan.forEach((i, slot) => {\n    const c = ronde[i];\n    const d = document.createElement(\"div\");\n    if (slot === bukaIdx) {\n      d.className = \"kartu buka\" + (baruBuka ? \" baruBuka\" : \"\");\n      d.id = \"kartuTerbuka\";\n      d.appendChild(kolomKartu(c, \"a\"));\n      d.appendChild(kolomKartu(c, \"b\"));\n      const slot = document.createElement(\"div\");\n      slot.className = \"slotNilai\";\n      if (terjawab) {\n        const bb = document.createElement(\"button\"); bb.className = \"mini benar\"; bb.textContent = \"Saya Benar\"; bb.onclick = () => nilai(true);\n        const bs = document.createElement(\"button\"); bs.className = \"mini salah\"; bs.textContent = \"Masih Salah\"; bs.onclick = () => nilai(false);\n        slot.appendChild(bb); slot.appendChild(bs);\n      } else {\n        const p = document.createElement(\"span\"); p.className = \"petunjukSlot\"; p.textContent = \"jawab dulu, lalu ketuk kolom tertutup\";\n        slot.appendChild(p);\n      }\n      d.appendChild(slot);\n    } else {\n      d.className = \"kartu tutup\";\n      const t = document.createElement(\"div\"); t.className = \"tanya\"; t.textContent = \"?\";\n      const n = document.createElement(\"div\"); n.className = \"nama\"; n.textContent = \"Kartu\";\n      const m = document.createElement(\"div\"); m.className = \"mikro\";\n      m.textContent = \"\";\n      d.appendChild(t); d.appendChild(n); d.appendChild(m);\n      d.onclick = () => bukaKartu(slot);\n    }\n    kisi.appendChild(d);\n  });\n  baruBuka = false;\n}\n\nfunction bukaKartu(slot) {\n  if (sibuk) return;\n  if (terjawab) { $(\"statusSesi\").textContent = \"Nilai dulu kartu yang sedang terbuka sebelum membuka kartu lain.\"; return; }\n  bukaIdx = slot; terjawab = false; baruBuka = true;\n  sisiTampil = Math.random() < 0.5 ? \"a\" : \"b\";\n  $(\"statusSesi\").textContent = \"Kartu dibuka: kolom \" + labelSisi(sisiTampil).toLowerCase() + \" yang tampil. Jawab kolom tertutupnya dari ingatan.\";\n  gambarReview();\n}\n\nfunction periksa() {\n  if (bukaIdx < 0 || sibuk) return;\n  terjawab = true;\n  $(\"statusSesi\").textContent = \"Bandingkan dengan jawabanmu, lalu nilai sendiri.\";\n  gambarReview();\n}\n\nasync function nilai(benar) {\n  if (bukaIdx < 0 || !terjawab || sibuk) return;\n  const gen = generasiSesi;\n  sibuk = true;\n  const st = keadaanKartu(urutan[bukaIdx]);\n  const el = $(\"kartuTerbuka\");\n  if (el) el.classList.add(benar ? \"flashBenar\" : \"flashSalah\");\n  if (benar) { st.benar++; if (st.benar >= 2) st.lulus = true; }\n  else { st.benar = 0; st.salah++; }\n  if (modeSesi === \"gantian\") {\n    if (benar) tallyTim[giliranTim]++;\n    giliranTim = (giliranTim + 1) % timSesi;\n  }\n  $(\"statusSesi\").textContent = benar ? \"Benar.\" : \"Masih salah.\";\n  await jeda(250);\n  if (gen !== generasiSesi) { sibuk = false; return; }\n  bukaIdx = -1; terjawab = false;\n  $(\"info\").textContent = infoTeks();\n  if (papanAktifSelesai()) {\n    $(\"barTim\").style.display = \"none\";\n    if (modeSesi === \"bergilir\" && !semuaTimSelesaiBabak()) {\n      $(\"areaReview\").style.display = \"none\";\n      $(\"teksTimSelesai\").textContent = \"Tim \" + (timAktif + 1) + \" · \" + ronde.length + \"/\" + ronde.length;\n      const tuntas = papanTim.filter(p => p.every(s => s.lulus)).length;\n      $(\"subTimSelesai\").textContent = tuntas + \" dari \" + timSesi + \" tim sudah menuntaskan babak ini.\";\n      $(\"areaTimSelesai\").style.display = \"\";\n      $(\"statusSesi\").textContent = \"Papan Tim \" + (timAktif + 1) + \" selesai. Lanjut ke tim berikutnya yang belum tuntas.\";\n      sibuk = false;\n      return;\n    }\n    if (modeSesi === \"kelas\") gambarReview();\n    $(\"areaReview\").style.display = \"none\";\n    if (langkahKe >= langkah.length - 1) {\n      $(\"cipTahap\").textContent = \"SELESAI\";\n      let teks = kartu.length + \"/\" + kartu.length + \" · \" + totalSesi() + \" sesi · \" + totalSesi() + \" pengumpulan\";\n      if (modeSesi === \"gantian\") teks += \" · Jawaban benar: \" + WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + tallyTim[t]).join(\" · \");\n      if (modeSesi === \"bergilir\") teks += \" · \" + WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + kartu.length + \"/\" + kartu.length).join(\" · \");\n      $(\"ringkasTuntas\").textContent = teks;\n      $(\"areaTuntas\").style.display = \"\";\n      $(\"statusSesi\").textContent = \"Semua babak selesai.\";\n    } else {\n      $(\"teksLangkah\").textContent = labelLangkah(langkahIni()) + \" · \" + ronde.length + \"/\" + ronde.length;\n      const rincian = $(\"rincianLangkah\");\n      if (modeSesi === \"gantian\") {\n        rincian.textContent = \"Jawaban benar: \" + WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + tallyTim[t]).join(\" · \");\n        rincian.style.display = \"\";\n      } else if (modeSesi === \"bergilir\") {\n        rincian.textContent = WARNA_TIM.slice(0, timSesi).map((w, t) => \"Tim \" + (t + 1) + \" · \" + papanTim[t].filter(s => s.lulus).length + \"/\" + ronde.length).join(\" · \");\n        rincian.style.display = \"\";\n      } else rincian.style.display = \"none\";\n      $(\"areaLangkah\").style.display = \"\";\n      $(\"statusSesi\").textContent = \"Babak selesai. Ulangi babak ini, atau lanjut ke babak berikutnya.\";\n    }\n    sibuk = false;\n    return;\n  }\n  const kisi = $(\"kisiReview\");\n  if (!gerakDikurangi()) kisi.style.opacity = \"0\";\n  await jeda(120);\n  if (gen !== generasiSesi) { sibuk = false; return; }\n  if (modeSesi === \"kelas\") urutan = kocok(urutan); else susunUrutan();\n  gambarReview();\n  segarkanBarTim();\n  kisi.style.opacity = \"1\";\n  sibuk = false;\n}\n\nfunction pindahTim() {\n  if (sibuk || modeSesi !== \"bergilir\") return;\n  if (bukaIdx >= 0) { $(\"statusSesi\").textContent = \"Nilai dulu kartu yang sedang terbuka sebelum berganti tim.\"; return; }\n  for (let lompat = 1; lompat <= timSesi; lompat++) {\n    const calon = (timAktif + lompat) % timSesi;\n    if (papanTim[calon] && !papanTim[calon].every(s => s.lulus)) {\n      timAktif = calon;\n      $(\"areaTimSelesai\").style.display = \"none\";\n      $(\"areaReview\").style.display = \"\";\n      bukaIdx = -1; terjawab = false;\n      susunUrutan();\n      $(\"info\").textContent = infoTeks();\n      segarkanBarTim();\n      $(\"statusSesi\").textContent = \"Papan Tim \" + (timAktif + 1) + \". Ketuk satu kartu. Satu kolom tampil, satu tertutup, diacak setiap dibuka, dan posisi kartu diacak lagi sesudah tiap penilaian.\";\n      gambarReview();\n      return;\n    }\n  }\n  $(\"statusSesi\").textContent = \"Semua tim sudah menuntaskan babak ini.\";\n}\n$(\"btnTimBerikutnya\").onclick = pindahTim;\n$(\"btnTimSelesaiLanjut\").onclick = pindahTim;\n\n$(\"btnUlangiLangkah\").onclick = () => { if (!sibuk) mulaiLangkah(); };\n$(\"btnLanjutLangkah\").onclick = () => {\n  if (sibuk) return;\n  langkahKe++;\n  mulaiLangkah();\n};\n\nlet ruang = [];\nlet sedangEdit = null;\nfunction hitungKartu(teks) {\n  if (typeof teks !== \"string\") return 0;\n  return parseDaftar(teks).hasil.length;\n}\nfunction sanitasiRuang() {\n  ruang = ruang.filter(x => x && typeof x === \"object\" && typeof x.daftar === \"string\");\n  const idTerpakai = new Set();\n  ruang.forEach((x, i) => {\n    if (typeof x.nama !== \"string\" || !x.nama.trim()) x.nama = \"Ruang \" + (i + 1);\n    if (typeof x.diubah !== \"number\" || !Number.isFinite(x.diubah)) x.diubah = Date.now();\n    if (typeof x.jumlah !== \"string\") x.jumlah = x.jumlah == null ? \"\" : String(x.jumlah);\n    if (typeof x.label !== \"string\" || !PASANGAN_LABEL[x.label]) x.label = \"kosakata\";\n    if (typeof x.id !== \"string\" || !x.id || idTerpakai.has(x.id)) x.id = \"r\" + Date.now() + \"-\" + i;\n    idTerpakai.add(x.id);\n    if (x.terakhir && !Array.isArray(x.terakhir.pool)) delete x.terakhir;\n  });\n}\nfunction muatRuang() {\n  try { const r = JSON.parse(localStorage.getItem(\"ruangKartuHafalan\") || \"[]\"); ruang = Array.isArray(r) ? r : []; }\n  catch (e) { ruang = []; }\n  sanitasiRuang();\n}\nfunction tulisRuang() { try { localStorage.setItem(\"ruangKartuHafalan\", JSON.stringify(ruang)); return true; } catch (e) { return false; } }\nfunction gambarRuang() {\n  const wadah = $(\"daftarRuang\");\n  wadah.innerHTML = \"\";\n  $(\"ruangKosong\").style.display = ruang.length ? \"none\" : \"\";\n  ruang.forEach(r => {\n    const d = document.createElement(\"div\");\n    d.style.cssText = \"background:#fff;border:2px solid var(--garis);border-radius:12px;padding:10px\";\n    const nm = document.createElement(\"div\");\n    nm.style.cssText = \"font-weight:700;font-size:14px;color:#20302a;overflow-wrap:anywhere\";\n    nm.textContent = r.nama;\n    const meta = document.createElement(\"div\");\n    meta.style.cssText = \"font-size:12px;color:var(--keterangan);margin:2px 0 8px\";\n    meta.textContent = hitungKartu(r.daftar) + \" kartu · \" + new Date(r.diubah).toLocaleDateString(\"id-ID\", { day: \"numeric\", month: \"short\" });\n    const bar = document.createElement(\"div\");\n    bar.style.cssText = \"display:flex;gap:8px;flex-wrap:wrap\";\n    const bBuka = document.createElement(\"button\");\n    bBuka.className = \"mini benar\"; bBuka.textContent = \"Buka\";\n    bBuka.onclick = () => bukaRuang(r.id);\n    const bNama = document.createElement(\"button\");\n    bNama.className = \"mini salah\"; bNama.textContent = \"Nama\";\n    bNama.onclick = () => gantiNamaRuang(r.id);\n    const bHapus = document.createElement(\"button\");\n    bHapus.className = \"mini salah\"; bHapus.textContent = \"Hapus\";\n    bHapus.style.color = \"#b03a2a\"; bHapus.style.borderColor = \"#b03a2a\";\n    bHapus.onclick = () => hapusRuang(r.id);\n    bar.appendChild(bBuka); bar.appendChild(bNama); bar.appendChild(bHapus);\n    d.appendChild(nm); d.appendChild(meta); d.appendChild(bar);\n    wadah.appendChild(d);\n  });\n}\nfunction bukaRuang(id) {\n  const r = ruang.find(x => x.id === id);\n  if (!r) return;\n  sedangEdit = id;\n  editorKotor = false;\n  $(\"daftar\").value = r.daftar;\n  $(\"namaRuang\").value = r.nama;\n  $(\"jumlahKartu\").value = r.jumlah || \"\";\n  $(\"jenisLabel\").value = r.label || \"kosakata\";\n  $(\"statusIsi\").textContent = \"Ruang \\\"\" + r.nama + \"\\\" dibuka: \" + hitungKartu(r.daftar) + \" kartu. Tekan Mulai Sesi untuk memakai, atau ubah daftarnya lalu Simpan Ruang untuk memperbarui.\";\n  $(\"statusRuang\").textContent = \"Sedang membuka ruang \\\"\" + r.nama + \"\\\". Menyimpan akan memperbarui ruang ini.\";\n}\nfunction gantiNamaRuang(id) {\n  const r = ruang.find(x => x.id === id);\n  if (!r) return;\n  const baru = window.prompt(\"Nama baru untuk ruang ini:\", r.nama);\n  if (baru === null) return;\n  const nama = baru.trim();\n  if (!nama) { $(\"statusRuang\").textContent = \"Nama tidak boleh kosong.\"; return; }\n  if (ruang.some(x => x.id !== id && x.nama === nama)) { $(\"statusRuang\").textContent = \"Nama \\\"\" + nama + \"\\\" sudah dipakai ruang lain.\"; return; }\n  r.nama = nama;\n  r.diubah = Date.now();\n  if (sedangEdit === id) $(\"namaRuang\").value = nama;\n  const ok = tulisRuang();\n  gambarRuang();\n  $(\"statusRuang\").textContent = ok ? \"Nama ruang diganti menjadi \\\"\" + nama + \"\\\".\" : \"Nama diganti di layar, tetapi GAGAL tersimpan di perangkat (penyimpanan penuh atau mode privat).\";\n}\nfunction hapusRuang(id) {\n  const r = ruang.find(x => x.id === id);\n  if (!r) return;\n  if (!window.confirm(\"Hapus ruang \\\"\" + r.nama + \"\\\" (\" + hitungKartu(r.daftar) + \" kartu) dari perangkat ini? Hapus ini permanen dan tidak bisa dikembalikan.\")) return;\n  ruang = ruang.filter(x => x.id !== id);\n  if (sedangEdit === id) sedangEdit = null;\n  const ok = tulisRuang();\n  gambarRuang();\n  if (!ok) $(\"statusRuang\").textContent = \"Ruang terhapus di layar, tetapi penghapusan GAGAL tersimpan di perangkat.\";\n}\n$(\"btnSimpanRuang\").onclick = () => {\n  const daftar = $(\"daftar\").value;\n  const n = hitungKartu(daftar);\n  if (n < 2) { $(\"statusRuang\").textContent = \"Daftar harus berisi minimal 2 kartu sebelum disimpan.\"; return; }\n  if (n > MAKS_KARTU) { $(\"statusRuang\").textContent = \"Satu ruang maksimal \" + MAKS_KARTU + \" kartu; daftar ini berisi \" + n + \" kartu. Kurangi dulu sebelum disimpan.\"; return; }\n  let nama = $(\"namaRuang\").value.trim();\n  if (!nama) {\n    let maks = 0;\n    ruang.forEach(x => { const m = /^Pertemuan (\\d+)$/.exec(x.nama); if (m) maks = Math.max(maks, parseInt(m[1], 10)); });\n    nama = \"Pertemuan \" + (maks + 1);\n  }\n  if (ruang.some(x => x.id !== sedangEdit && x.nama === nama)) {\n    $(\"statusRuang\").textContent = \"Nama \\\"\" + nama + \"\\\" sudah dipakai ruang lain. Buka ruang itu untuk memperbaruinya, atau pilih nama lain.\";\n    return;\n  }\n  let pesan;\n  if (sedangEdit) {\n    const r = ruang.find(x => x.id === sedangEdit);\n    if (r) { r.nama = nama; r.daftar = daftar; r.jumlah = $(\"jumlahKartu\").value; r.label = $(\"jenisLabel\").value; r.diubah = Date.now(); }\n    pesan = \"Tersimpan, ruang \\\"\" + nama + \"\\\" diperbarui.\";\n  } else {\n    const r = { id: \"r\" + Date.now() + \"-\" + acak(100000), nama, daftar, jumlah: $(\"jumlahKartu\").value, label: $(\"jenisLabel\").value, diubah: Date.now() };\n    ruang.push(r);\n    sedangEdit = r.id;\n    pesan = \"Ruang baru \\\"\" + nama + \"\\\" tersimpan.\";\n  }\n  $(\"namaRuang\").value = nama;\n  const ok = tulisRuang();\n  gambarRuang();\n  editorKotor = false;\n  $(\"statusRuang\").textContent = ok ? pesan : \"GAGAL tersimpan di perangkat (penyimpanan penuh atau mode privat). Ruang ini hanya ada di layar selama halaman terbuka.\";\n};\n$(\"btnRuangBaru\").onclick = () => {\n  const adaIsi = $(\"daftar\").value.trim() !== \"\" || $(\"namaRuang\").value.trim() !== \"\";\n  if (adaIsi && !window.confirm(\"Mulai ruang baru? Isi formulir sekarang akan dikosongkan; perubahan yang belum disimpan akan hilang.\")) return;\n  sedangEdit = null;\n  editorKotor = false;\n  $(\"namaRuang\").value = \"\";\n  $(\"daftar\").value = \"\";\n  $(\"jumlahKartu\").value = \"\";\n  $(\"jenisLabel\").value = \"kosakata\";\n  $(\"statusRuang\").textContent = \"Ruang baru: ketik daftar kartu dan namanya, lalu tekan Simpan Ruang.\";\n  segarkanStatusIsi();\n  $(\"daftar\").focus();\n};\n$(\"btnSalinCadangan\").onclick = async () => {\n  const teks = JSON.stringify(ruang);\n  try {\n    await navigator.clipboard.writeText(teks);\n    $(\"statusCadangan\").textContent = \"Cadangan \" + ruang.length + \" ruang tersalin. Simpan teksnya di tempat aman.\";\n  } catch (e) {\n    window.prompt(\"Salin teks cadangan ini:\", teks);\n  }\n};\n$(\"btnPulihkanCadangan\").onclick = () => {\n  const teks = window.prompt(\"Tempel teks cadangan ruang di sini. Semua ruang yang ada akan digantikan:\");\n  if (!teks) return;\n  try {\n    const data = JSON.parse(teks);\n    if (!Array.isArray(data)) throw new Error(\"bukan daftar\");\n    ruang = data;\n    sedangEdit = null;\n    sanitasiRuang();\n    const ok = tulisRuang();\n    gambarRuang();\n    $(\"statusCadangan\").textContent = ok ? ruang.length + \" ruang dipulihkan dari cadangan.\" : \"Cadangan terbaca, tetapi gagal ditulis ke perangkat.\";\n  } catch (e) {\n    $(\"statusCadangan\").textContent = \"Teks cadangan tidak terbaca; tidak ada yang diubah.\";\n  }\n};\nfunction segarkanStatusIsi() {\n  if (document.body.classList.contains(\"sesiAktif\")) return;\n  const n = hitungKartu($(\"daftar\").value);\n  $(\"statusIsi\").textContent = n + \" kartu terisi. Tekan Mulai Sesi, atau ganti dulu daftarnya dengan kosakata dars apa pun.\" + (editorKotor ? \" Ada perubahan yang belum disimpan sebagai ruang.\" : \"\");\n}\n[\"daftar\", \"namaRuang\", \"jumlahKartu\"].forEach(id => $(id).addEventListener(\"input\", () => { editorKotor = true; segarkanStatusIsi(); }));\n$(\"jenisLabel\").addEventListener(\"change\", () => { editorKotor = true; });\nwindow.addEventListener(\"beforeunload\", e => {\n  if (document.body.classList.contains(\"sesiAktif\") && $(\"areaTuntas\").style.display === \"none\") { e.preventDefault(); e.returnValue = \"\"; }\n});\ntry { muatRuang(); gambarRuang(); } catch (e) { ruang = []; }\nsegarkanStatusIsi();\n\nfunction segarkanPemilihMode() {\n  $(\"wadahTim\").style.display = $(\"pilihMode\").value === \"kelas\" ? \"none\" : \"inline-flex\";\n}\nfunction simpanPilihanMode() {\n  try {\n    localStorage.setItem(\"modeKartuHafalan\", JSON.stringify({ mode: $(\"pilihMode\").value, tim: parseInt($(\"pilihTim\").value, 10) || 2 }));\n  } catch (e) {}\n  segarkanPemilihMode();\n}\ntry {\n  const mp = JSON.parse(localStorage.getItem(\"modeKartuHafalan\") || \"null\");\n  if (mp && [\"kelas\", \"gantian\", \"bergilir\"].includes(mp.mode)) $(\"pilihMode\").value = mp.mode;\n  if (mp && [2, 3, 4].includes(mp.tim)) $(\"pilihTim\").value = String(mp.tim);\n} catch (e) {}\nsegarkanPemilihMode();\n$(\"pilihMode\").addEventListener(\"change\", simpanPilihanMode);\n$(\"pilihTim\").addEventListener(\"change\", simpanPilihanMode);\n\nfunction pasangTema(nama) {\n  document.body.classList.remove(\"tema-zamrud\", \"tema-biru\", \"tema-terang\");\n  document.body.classList.add(\"tema-\" + nama);\n  try { localStorage.setItem(\"temaKartuHafalan\", nama); } catch (e) {}\n  document.querySelectorAll(\".btnTema\").forEach(b => b.classList.toggle(\"aktif\", b.dataset.tema === nama));\n}\ndocument.querySelectorAll(\".btnTema\").forEach(b => { b.onclick = () => pasangTema(b.dataset.tema); });\nlet temaAwal = \"zamrud\";\ntry { temaAwal = localStorage.getItem(\"temaKartuHafalan\") || \"zamrud\"; } catch (e) {}\nif (![\"zamrud\", \"biru\", \"terang\"].includes(temaAwal)) temaAwal = \"zamrud\";\npasangTema(temaAwal);\n\n$(\"btnMulai\").onclick = mulaiSesi;\n$(\"btnLanjutReview\").onclick = mulaiReview;\n$(\"btnMainLagi\").onclick = mulaiSesi;\n$(\"btnUlang\").onclick = () => {\n  const sesiJalan = $(\"kotakSesi\").style.display !== \"none\" && $(\"areaTuntas\").style.display === \"none\";\n  if (sesiJalan && !window.confirm(\"Akhiri sesi sekarang? Kemajuan sesi ini akan hilang.\")) return;\n  generasiSesi++;\n  sibuk = false;\n  clearInterval(jamBelajar);\n  document.body.classList.remove(\"sesiAktif\");\n  $(\"kotakSesi\").style.display = \"none\";\n  $(\"kotakIsi\").style.display = \"\";\n};\n</script>\n</body>\n</html>\n";
